package dev.rdf.kaptlib

import dagger.Component
import javax.inject.Inject

class Engine @Inject constructor() {
    fun name(): String = "kapt"
}

/** Its implementation, DaggerGarage, is generated by Dagger's annotation processor through kapt. */
@Component
interface Garage {
    fun engine(): Engine
}

object Kapt {
    fun run(): String = DaggerGarage.create().engine().name()
}
